const content = $json.content;
const fileName = $json.fileName;

const matches = content.match(/xmlUrl=["']([^"']+)["']/gi);
const results = [];

for (const match of matches) {
  const url = match.replace(/xmlUrl=["']/i, '').replace(/["']$/, '');
  results.push({ json: { feedUrl: url, sourceFile: fileName } });
}

return results;

